mapper.select:
SELECT B.BATCH_SEQ_NO AS seqno, /**批处理任务组执行ID**/ C.TASK_ID AS taskId /**任务代码**/ FROM SYS_BATCH_EXEC_INFO A INNER JOIN SYS_BATCHGRP_EXEC_INFO B ON A.BATCH_EXEDETAIL_SEQ_NO = B.SEQ_NO INNER JOIN SYS_BATCH_JOB C ON B.BATCH_SEQ_NO = C.BATCH_SEQ_NO INNER JOIN SYS_BATCH_TASK E ON E.TASK_ID = C.TASK_ID WHERE 1=1
AND A.SEQ_NO = #{SEQ_NO,jdbcType=VARCHAR}
ORDER BY E.TASK_PRI ASC
